int save_xstate(struct xsave_struct *fx, u64 mask) {
    int ret = 0;

    // Use the appropriate xsave instruction based on available features
    asm volatile (
        // Alternative for xsaveopt
        ".alternative_if 1\n\t"
        "xsaveopt %0\n\t"
        ".alternative_else\n\t"
        // Alternative for xsaves
        "xsaves %0\n\t"
        ".alternative_endif"
        : 
        : "m"(*fx), "i"(mask)
    );

    return ret;
}

int save_xstate(struct xsave_struct *fx, u64 mask) {
    int ret = 0;

    asm volatile(
        ".alternative_if   0, x86_capable.xsave\n"
        "xsave %0, %1\n"
        ".alternative_elseif 1, x86_capable.xsaveopt\n"
        "xsaveopt %0, %1\n"
        ".alternative_elseif 2, x86_capable.xsaves\n"
        "xsaves %0, %1\n"
        ".alternative_else\n"
        " /* Fallback if none are available */\n"
        ".alternative_endif"
        : /* No outputs */
        : "m"(*fx), "n"(mask)
        : "memory"
    );

    return ret;
}

int save_processor_state(struct xsave_struct *fx, u64 mask) {
    int ret = 0;

    asm volatile(
        "alternative_if_not .Lno_xsaves\n"
        "  xsaves %0, %1\n"
        "alternative_else\n"
        "  xsaveopt %0, %1\n"
        "alternative_endif"
        : : "m"(*fx), "r"(mask) : "memory");

    return ret;
}

int save_xsave_state(struct xsave_struct *fx, u64 mask) {
    int err = 0;

    asm volatile(
        ".alternative_if_not 0,*,*,xsave"
        "xsave %[fx]; "
        ".alternative_else 0,*,*,xsaveopt"
        "xsaveopt %[fx]; "
        ".alternative_else 0,*,*,xsaves"
        "xsaves %[fx], %[mask]"
        ".alternative_endif"
        : [fx] "+m"(*fx)
        : [mask] "r"(mask)
        : "memory");

    return err;
}

int save_extended_processor_state(struct xsave_struct *fx, u64 mask)
{
    int error = 0;

    asm volatile(
        "xsave %[fx];"
        :
        : [fx] "m"(*fx), "m"(mask)
        : "memory");

    return error;
}
